package com.aistock.prediction.analysis;
import com.fasterxml.jackson.databind.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import com.aistock.prediction.forecast.ForecastRecords;
class AnalysisPredictionFactsTest {
 final ObjectMapper m=new ObjectMapper();
 ForecastRecords.Record record(){var s=m.createObjectNode();s.putObject("input").put("originDate","2026-09-29").put("originRawClose","100").put("inputVersionId",UUID.randomUUID().toString()).put("rawVersionId",UUID.randomUUID().toString()).put("inputHash","a".repeat(64));var pts=s.putObject("prediction").put("publicationRevision",1).put("referenceBasis","ORIGIN_RAW").putArray("points");for(int i=1;i<=5;i++)pts.addObject().put("step",i).put("targetDate",LocalDate.parse("2026-10-07").plusDays(i).toString()).put("referencePrice",Integer.toString(90+i));var model=m.createObjectNode().put("artifactId","transformer").put("manifestHash","b".repeat(64)).put("checkpointHash","c".repeat(64));model.putObject("manifest").put("trainingCutoff","2023-12-31");return new ForecastRecords.Record(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),"SH600030",5,"SUCCEEDED",null,model,s,false,Instant.EPOCH,Instant.EPOCH);}
 @Test void risingBelowOriginAndNoActualSampleRemainDifferentFacts()throws Exception{var market=AnalysisFacts.build(new AnalysisFactsTest().sample(),"model",m);var r=record();var ref=new AnalysisPredictionSource.Reference(r,null);var f=AnalysisPredictionFacts.combine(market,r.predictionId(),ref,"model",m);assertTrue(f.values().get("PRED_TREND").contains("上行"));assertEquals("均低于原点收盘价",f.values().get("PRED_RELATIVE_ORIGIN"));assertTrue(f.values().get("PRED_P1").contains("非实际行情"));assertTrue(f.values().get("PRED_VERIFICATION").contains("尚无"));assertTrue(f.values().get("PRED_CONTEXT_RELATION").contains("2026-09-29"));assertEquals(f.hash(),AnalysisPredictionFacts.combine(market,r.predictionId(),ref,"model",m).hash());assertEquals("grounded-stock-analysis-prediction-v2",f.context().path("promptVersion").asText());}
 @Test void verificationVersionsChangeHashAndDoNotInventMetrics()throws Exception{var market=AnalysisFacts.build(new AnalysisFactsTest().sample(),"model",m);var r=record();var v=m.createObjectNode().put("verificationVersionId",UUID.randomUUID().toString()).put("dueThrough","2026-10-08");v.putObject("result").put("verifiedCount",0).putObject("metrics");var zero=AnalysisPredictionFacts.combine(market,r.predictionId(),new AnalysisPredictionSource.Reference(r,v),"model",m);assertTrue(zero.values().get("PRED_VERIFICATION").contains("不能评价"));assertFalse(zero.values().containsKey("PRED_METRICS"));((com.fasterxml.jackson.databind.node.ObjectNode)v.path("result")).put("verifiedCount",2);v.put("verificationVersionId",UUID.randomUUID().toString());var partial=AnalysisPredictionFacts.combine(market,r.predictionId(),new AnalysisPredictionSource.Reference(r,v),"model",m);assertNotEquals(zero.hash(),partial.hash());assertTrue(partial.values().get("PRED_VERIFICATION").contains("2个"));assertFalse(partial.values().containsKey("PRED_METRICS"));}
}
